175	    28	/**
176	    29	 * Maps exceptions to RFC 7807 {@link ProblemDetail} responses ({@code application/problem+json}).
177	    30	 * <p>
178	    31	 * Extends {@link ResponseEntityExceptionHandler}, so every standard Spring MVC exception (405, 406, 415,
179	    32	 * unknown path 404, ...) is a problem detail as well. Validation problems carry an extra {@code errors}
180	    33	 * property (field or parameter name to message). 401/403 raised by the security filters are produced by the
181	    34	 * security entry point and access denied handler; {@link UnauthorizedException} covers the 401 raised inside
182	    35	 * the application (invalid refresh token).
183	    36	 */
184	    37	@RestControllerAdvice
185	    38	@Slf4j
186	    39	public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {
187	    40	
188	    41	    private static final String ERRORS = "errors";
189	    42	    private static final String VALIDATION_TITLE = "Validation failed";
190	    43	    private static final String FALLBACK_MESSAGE = "invalid value";
191	    44	
192	    45	    @Override
