194	    47	                                                                  HttpHeaders headers, HttpStatusCode status,
195	    48	                                                                  WebRequest request) {
196	    49	        Map<String, String> errors = new TreeMap<>();
197	    50	        ex.getBindingResult().getFieldErrors().forEach(
198	    51	                error -> errors.putIfAbsent(error.getField(), messageOf(error)));
199	    52	        return handleExceptionInternal(ex, validationProblem(errors), headers, status, request);
200	    53	    }
201	    54	
202	    55	    @Override
203	    56	    protected ResponseEntity<Object> handleHandlerMethodValidationException(HandlerMethodValidationException ex,
204	    57	                                                                            HttpHeaders headers,
205	    58	                                                                            HttpStatusCode status,
206	    59	                                                                            WebRequest request) {
207	    60	        Map<String, String> errors = new TreeMap<>();
208	    61	        ex.getParameterValidationResults().forEach(result -> {
209	    62	            String name = result.getMethodParameter().getParameterName();
210	    63	            result.getResolvableErrors().forEach(
211	    64	                    error -> errors.putIfAbsent(name == null ? FALLBACK_MESSAGE : name, messageOf(error)));
212	    65	        });
213	    66	        return handleExceptionInternal(ex, validationProblem(errors), headers, status, request);
214	    67	    }
215	    68	
