260	   113	    }
261	   114	
262	   115	    /** Last resort: unexpected failures become a generic 500 problem without leaking internals. */
263	   116	    @ExceptionHandler(Exception.class)
264	   117	    public ProblemDetail handleUnexpected(Exception ex) {
265	   118	        log.error("Unhandled exception", ex);
266	   119	        return problem(HttpStatus.INTERNAL_SERVER_ERROR, "Internal server error", "An unexpected error occurred");
267	   120	    }
268	   121	
269	   122	    private static ProblemDetail validationProblem(Map<String, String> errors) {
270	   123	        ProblemDetail problem = problem(HttpStatus.BAD_REQUEST, VALIDATION_TITLE, "Request validation failed");
