272	   125	        return problem;
273	   126	    }
274	   127	
275	   128	    private static ProblemDetail problem(HttpStatus status, String title, String detail) {
276	   129	        log.debug("Responding {} {}: {}", status.value(), title, detail);
277	   130	        ProblemDetail problem = ProblemDetail.forStatusAndDetail(status, detail);
