   125	            throw new ValidationException("startTime and endTime must be whole minutes (seconds must be zero)");
   126	        }
   127	        if (!start.isBefore(end)) {
   128	            throw new ValidationException("startTime must be before endTime");
   129	        }
   130	        if (start.isBefore(clock.instant())) {
   131	            throw new ValidationException("startTime must not be in the past");
   132	        }
   133	        Duration duration = Duration.between(start, end);
   134	        Duration min = properties.reservation().minDuration();
   135	        Duration max = properties.reservation().maxDuration();
   136	        if (duration.compareTo(min) < 0) {
   137	            throw new ValidationException("Reservation must last at least " + min.toMinutes() + " minutes");
   138	        }
   139	        if (duration.compareTo(max) > 0) {
   140	            throw new ValidationException("Reservation must last at most " + max.toMinutes() + " minutes");
   141	        }
